<template>
 <view class="wholesale-ui" :class="dialog ? 'wh-overlay' : 'wh-form-page'">
  <view :class="dialog ? 'wh-dialog' : 'wh-body'">
   <view v-if="dialog" class="wh-dialog-head">{{kind==='quota-transfer'?'划拨名额':'购买VIP名额'}}<button role="button" class="wh-close" aria-label="关闭弹窗" @click="back"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view>
   <FeaturePageState :status="status" :error="error" @retry="load"/>
   <template v-if="status==='ready' && options">
    <view v-if="result" class="wh-finish"><view>{{result.status==='PENDING_PAYMENT'?'订单待支付':result.status==='PENDING_REVIEW'?'提现申请已提交，等待审核':'操作已完成'}}</view><button v-if="result.orderId && result.status==='PENDING_PAYMENT'" class="wh-primary wh-pill" @click="pay">去支付</button><button class="wh-secondary wh-pill" @click="back">返回上一页</button><button v-if="kind==='withdraw'" class="wh-link" @click="records">查看提现记录</button></view>
    <template v-else>
     <picker v-if="memberChoices.length && !pageQuery?.targetAccountId" :range="memberChoices" range-key="label" @change="set('targetAccountId',memberChoices[$event.detail.value].value)"><view class="wh-member-picker wh-card">受益成员　{{person?.name || '请选择成员'}} <image src="/static/common/icon-chevron-right.png" mode="aspectFit"/></view></picker>
     <view v-if="person && kind!=='bind-store'" class="wh-person wh-selected-person" :class="{'wh-card':!dialog}"><image v-if="person.avatarUrl" :src="person.avatarUrl" class="wh-avatar" mode="aspectFill"/><view v-else class="wh-avatar">{{person.name?.slice(0,1)}}</view><text>{{person.name}}</text><text class="wh-tag">{{person.levelLabel || '普通用户'}}</text></view>
     <template v-if="dialog">
      <view class="wh-row wh-datum"><text>{{kind==='quota-transfer'?'划拨数量':'购买数量'}}</text><text v-if="kind==='quota-transfer'">剩余<text class="wh-blue">{{options.standardRemaining ?? '—'}}个</text>VIP名额</text></view><input :value="draft.quantity" class="wh-input wh-quantity" type="number" :maxlength="4" placeholder="请输入数量" :disabled="busy" @input="set('quantity',$event.detail.value)"/>
      <view v-if="kind==='quota-purchase'" class="wh-datum"><view><text>购买单价</text><view><text class="wh-blue">¥{{money(options.unitAmount)}}/个</text><view class="wh-muted">{{options.pricingLabel || '合伙人购买价格以报价为准'}}</view></view></view></view>
      <view class="wh-datum wh-total"><view><text>合计金额</text><text class="wh-blue">{{quoteAmount==null?'—':`¥${money(quoteAmount)}`}}</text></view></view>
     </template>
     <template v-else-if="kind==='upgrade'">
      <view class="wh-card"><text>请选择等级</text><view class="wh-plan-grid"><button v-for="plan in plans" :key="plan.value" :class="{selected:draft.targetLevel===plan.value}" :disabled="busy || plan.disabled" @click="choosePlan(plan)">{{plan.label}}</button></view><text v-if="plan" class="wh-muted wh-blue">{{plan.label}}{{plan.description || ''}}</text></view>
      <view class="wh-card"><text>请选择名额</text><view class="wh-quota-grid"><view v-for="source in sources" :key="source.key"><text class="wh-muted">{{source.label}}VIP余额</text><view>{{source.remaining ?? '—'}}个</view><view class="wh-stepper"><text>使用数量</text><button :disabled="busy || Number(draft[source.key])<=0" @click="adjust(source.key,-1)">−</button><text>{{draft[source.key] || 0}}</text><button :disabled="busy || Number(draft[source.key])>=source.remaining" @click="adjust(source.key,1)">+</button></view></view></view><text v-if="plan" class="wh-muted wh-blue">需消耗{{plan.requiredQuota ?? '—'}}个VIP名额即可升级</text></view>
      <view v-if="quote && Number(draft.activityQuantity)>0" class="wh-card"><text>服务费明细</text><view class="wh-datum"><view v-for="line in quote.details" :key="line.label"><text class="wh-muted">{{line.label}}</text><text>{{format(line)}}</text></view></view></view>
     </template>
     <template v-else-if="kind==='bind-store'">
      <view class="wh-region wh-row"><text>区域选择</text><RegionPicker :label="region.names.join('') || '全部地区'" :codes="region.codes" plain @change="region=$event"/><button v-if="region.codes.length" class="wh-link" @click="region={codes:[],names:[]}">全部</button></view>
      <view class="wh-card wh-store-list"><button v-if="options.headquarters" class="wh-store" :disabled="busy" @click="chooseStore(options.headquarters)"><view><view>总部服务</view><text class="wh-muted">当前地区没有可服务门店时，可选择总部服务</text></view><image class="wh-chevron" src="/static/common/icon-chevron-right.png" mode="aspectFit"/></button><button v-for="store in stores" :key="store.id" class="wh-store" :disabled="busy" @click="chooseStore(store)"><image class="wh-store-cover" :src="store.coverUrl || '/static/common/icon-store.png'" mode="aspectFill"/><view><view>{{store.name}} <text class="wh-tag">{{store.number}}</text></view><view class="wh-muted">店长信息：{{store.manager || '—'}}<text v-if="store.phone">/{{store.phone}}</text></view><view class="wh-muted">{{store.address}}</view></view><image class="wh-chevron" src="/static/common/icon-chevron-right.png" mode="aspectFit"/></button><EmptyState v-if="!stores.length" text="当前地区暂无服务门店"/></view>
     </template>
     <template v-else-if="kind==='withdraw'">
      <view class="wh-card"><text>提现金额</text><input :value="draft.amount" class="wh-input" type="digit" :maxlength="15" placeholder="请输入提现金额" :disabled="busy" @input="set('amount',$event.detail.value)"/><view class="wh-available">可提现金额 <text class="wh-blue">¥{{money(available)}}</text></view></view>
      <view class="wh-card"><text>提现账户类型</text><view class="wh-plan-grid wh-account-types"><button v-for="type in accountTypes" :key="type.value" :class="{selected:draft.accountType===type.value}" :disabled="busy" @click="changeType(type.value)">{{type.label}}</button></view><text class="wh-block-label">{{draft.accountType==='COMPANY'?'公司名称':'开户姓名'}}</text><input v-model="payee.name" class="wh-input" placeholder="请输入" :maxlength="60" :disabled="busy" @input="clearPayee"/><text class="wh-block-label">银行名称</text><input v-model="payee.bankName" class="wh-input" placeholder="请输入" :maxlength="60" :disabled="busy" @input="clearPayee"/><text class="wh-block-label">银行卡号</text><input v-model="payee.bankNumber" class="wh-input" type="number" placeholder="请输入" :maxlength="19" :disabled="busy" @input="clearPayee"/></view>
     </template>
     <text v-if="operationError" class="wh-error" role="alert">{{operationError}}</text>
     <view v-if="dialog" class="wh-confirm"><button v-if="kind==='quota-purchase'" class="wh-secondary wh-pill" :disabled="busy" @click="back">取消</button><button role="button" class="wh-primary wh-pill" :disabled="busy || !canQuote" @click="submit">{{busy?'处理中…':kind==='quota-transfer'?'确认划拨':'立即支付'}}</button></view>
    </template>
   </template>
  </view>
  <view v-if="!dialog && status==='ready' && !result && kind!=='bind-store'" class="wh-bottom"><button role="button" class="wh-primary" :disabled="busy || !canQuote" @click="submit">{{busy?'处理中…':kind==='withdraw'?'申请提现':quoteAmount>0?`支付¥${money(quoteAmount)}立即升级`:'确认升级'}}</button></view>
  <view v-if="confirmation" class="wh-overlay wh-confirm-mask"><view class="wh-dialog"><view class="wh-dialog-head">{{kind==='bind-store'?'确定要绑定该门店吗？':'请确认本次操作'}}</view><view v-if="quote" class="wh-datum"><view v-for="line in quote.details" :key="line.label"><text>{{line.label}}</text><text>{{format(line)}}</text></view></view><text v-if="operationError" class="wh-error">{{operationError}}</text><view class="wh-confirm"><button class="wh-secondary wh-pill" :disabled="busy" @click="confirmation=false">取消</button><button role="button" class="wh-primary wh-pill" :disabled="busy || !canSubmit" @click="commit">{{busy?'提交中…':'确定'}}</button></view></view></view>
 </view>
</template>
<script setup>
import {ref,computed,watch,onUnmounted} from 'vue'
import {money,percent} from '../features/exclusive/format'
import {getBusinessContext} from '../services/business'
import {getBusinessOperationOptions,previewBusinessOperation,commitBusinessOperation,registerBusinessPayee} from '../services/business-operations'
import {getCommerceOrder} from '../services/commerce'
import {useAsyncPage} from '../composables/useAsyncPage'
import FeaturePageState from './FeaturePageState.vue'
import EmptyState from './EmptyState.vue'
import RegionPicker from './RegionPicker.vue'
const props=defineProps({kind:String,pageQuery:Object}),context=ref(null),draft=ref({}),quote=ref(null),result=ref(null),busy=ref(false),operationError=ref(''),confirmation=ref(false),region=ref({codes:[],names:[]}),payee=ref({name:'',bankName:'',bankNumber:''})
let epoch=0,active=true,key='',receivedAt=0,quoteTimer=null
const {data:options,status,error,load}=useAsyncPage(async()=>{const ctx=await getBusinessContext(props.kind==='withdraw'?null:'wholesale',props.pageQuery?.contextId),value=await getBusinessOperationOptions(props.kind,ctx.id);if(!Array.isArray(value?.fields)||!Array.isArray(value.allowedActions))throw new Error('操作配置异常');context.value=ctx;draft.value={targetAccountId:props.pageQuery?.targetAccountId || '',quantity:'',accountType:'PERSONAL',amount:'',standardQuantity:0,activityQuantity:0};quote.value=null;result.value=null;key='';confirmation.value=false;return value},false)
watch(()=>props.pageQuery,q=>{if(q)load()},{immediate:true})
const dialog=computed(()=>['quota-transfer','quota-purchase'].includes(props.kind)),memberChoices=computed(()=>options.value?.fields.find(f=>f.key==='targetAccountId')?.options || []),person=computed(()=>options.value?.members?.find(p=>p.id===draft.value.targetAccountId)),plans=computed(()=>person.value?.upgradePlans || options.value?.upgradePlans || options.value?.fields.find(f=>f.key==='targetLevel')?.options || []),plan=computed(()=>plans.value.find(p=>p.value===draft.value.targetLevel)),sources=computed(()=>[{key:'activityQuantity',label:'活动',remaining:options.value?.activityRemaining},{key:'standardQuantity',label:'标准',remaining:options.value?.standardRemaining}]),accountTypes=[{value:'PERSONAL',label:'个人账户'},{value:'COMPANY',label:'公司账户'}]
const stores=computed(()=>(options.value?.stores || []).filter(s=>!region.value.codes.length || region.value.codes.every((code,index)=>s.regionCodes?.[index]===code)))
const canQuote=computed(()=>options.value?.allowedActions.includes('quote')),canSubmit=computed(()=>options.value?.allowedActions.includes('submit')),available=computed(()=>options.value?.balances?.find(x=>x.kind==='money')?.value),quoteAmount=computed(()=>quote.value?.amount ?? quote.value?.details?.find(x=>['待支付金额','服务费','合计金额'].includes(x.label))?.value ?? null)
const format=line=>line.kind==='money'?`¥${money(line.value)}`:line.kind==='percent'?percent(line.value):line.value??'—'
function invalidate(){clearTimeout(quoteTimer);++epoch;quote.value=null;key='';operationError.value='';confirmation.value=false}
function set(field,value){if(busy.value)return;draft.value[field]=value;invalidate()}
function clearPayee(){draft.value.payeeToken='';invalidate()}
function changeType(value){if(busy.value)return;draft.value.accountType=value;payee.value={name:'',bankName:'',bankNumber:''};clearPayee()}
function choosePlan(value){set('targetLevel',value.value);draft.value.standardQuantity=value.requiredQuota || 0;draft.value.activityQuantity=0}
function adjust(field,delta){set(field,Math.max(0,Number(draft.value[field] || 0)+delta))}
async function prepare(){const current=epoch;const output=await previewBusinessOperation(props.kind,context.value.id,draft.value);if(!active||current!==epoch)return false;quote.value=output;receivedAt=Date.now();return true}
watch(()=>[draft.value.quantity,draft.value.targetAccountId,draft.value.targetLevel,draft.value.standardQuantity,draft.value.activityQuantity],()=>{
 clearTimeout(quoteTimer)
 const quantityReady=['quota-transfer','quota-purchase'].includes(props.kind) && /^[1-9]\d{0,3}$/.test(String(draft.value.quantity)) && (props.kind==='quota-purchase' || draft.value.targetAccountId)
 const upgradeReady=props.kind==='upgrade' && draft.value.targetAccountId && plan.value && Number(draft.value.standardQuantity)+Number(draft.value.activityQuantity)===plan.value.requiredQuota
 if(!canQuote.value || (!quantityReady && !upgradeReady))return
 quoteTimer=setTimeout(async()=>{try{await prepare()}catch{/* field validation is reported on explicit submission */}},300)
})
async function submit(){if(busy.value||!canQuote.value)return;clearTimeout(quoteTimer);++epoch;busy.value=true;operationError.value='';try{if(props.kind==='withdraw'&&!draft.value.payeeToken){const token=await registerBusinessPayee(context.value.id,{...payee.value,accountType:draft.value.accountType});draft.value.payeeToken=token.payeeToken}if(await prepare())confirmation.value=true}catch(e){operationError.value=e.message}finally{if(active)busy.value=false}}
async function chooseStore(store){if(busy.value)return;set('storeId',store.id);await submit()}
async function commit(){if(busy.value||!quote.value||!canSubmit.value)return;if(quote.value.expiresAt<=quote.value.serverTime+Date.now()-receivedAt){operationError.value='预览已过期，请重新确认';confirmation.value=false;quote.value=null;return}const current=epoch;busy.value=true;operationError.value='';if(!key)key=`wholesale-${Date.now()}-${Math.random().toString(36).slice(2)}`;try{const output=await commitBusinessOperation(props.kind,context.value.id,quote.value.id,key);if(!active||current!==epoch)return;result.value=output;confirmation.value=false;payee.value={name:'',bankName:'',bankNumber:''};if(output.orderId)pay()}catch(e){if(active&&current===epoch)operationError.value=e.message}finally{if(active)busy.value=false}}
function pay(){uni.navigateTo({url:`/pages/payment/cashier?orderId=${encodeURIComponent(result.value.orderId)}`})}
function records(){uni.navigateTo({url:`/pages/wallet/withdrawals?contextId=${encodeURIComponent(context.value.id)}`})}
function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.switchTab({url:'/pages/partners/index'})}
async function refresh(){if(busy.value)return;if(result.value?.orderId){try{const value=await getCommerceOrder(result.value.orderId);if(value.order.status==='COMPLETED')result.value={...result.value,status:'PAID'};else if(value.order.status==='CANCELLED')result.value={...result.value,status:'CANCELLED'}}catch(e){operationError.value=e.message}return}if(!quote.value&&!result.value)load()}
onUnmounted(()=>{clearTimeout(quoteTimer);active=false;++epoch;payee.value={name:'',bankName:'',bankNumber:''}});defineExpose({refresh})
</script>
<style>@import '../styles/wholesale.css';</style>
<style scoped>
.wh-selected-person{justify-content:center;padding:.8em;margin-bottom:1em;background:#464c6b;border-radius:.5em}.wh-member-picker{display:flex;justify-content:space-between;align-items:center;font-size:.9em}.wh-member-picker image,.wh-chevron{height:1em;width:1em;flex-shrink:0}.wh-quantity{text-align:center;margin:.5em 0 1.4em}.wh-total{margin:.6em 0}.wh-plan-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5em;margin:.6em 0}.wh-plan-grid button{font-size:.9em;color:#e1e4f3;background:#464b69;border:1rpx solid transparent;border-radius:.25em;line-height:2.4;padding:.2em;margin:0;min-width:0}.wh-plan-grid .selected{background:#09264c;border:1rpx solid #55adff;color:#55adff}.wh-quota-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5em;margin:.7em 0}.wh-quota-grid>view{background:#464b69;text-align:center;padding:.7em .3em;border-radius:.3em}.wh-stepper{display:flex;align-items:center;justify-content:center;gap:.25em;margin-top:1em;font-size:.8em;white-space:nowrap}.wh-stepper>text:first-child{font-size:.8em;margin-right:auto}.wh-stepper button{display:flex;align-items:center;justify-content:center;background:#09264c;border:1rpx solid #4389d6;border-radius:50%;width:1.2em;height:1.2em;line-height:1;padding:0;margin:0;color:#fff;font-size:1em}.wh-stepper button[disabled]{opacity:.4}.wh-available{text-align:right;font-size:.85em}.wh-account-types{margin-bottom:1.3em}.wh-region{font-size:.85em;margin-bottom:.8em}.wh-region>picker{flex:1;min-width:0}.wh-store-list{padding:.7em}.wh-store{display:flex;align-items:center;gap:.6em;text-align:left;width:100%;background:none;color:white;font-size:.9em;padding:.6em 0;margin:0;line-height:1.7;border-bottom:1rpx solid #575c7433}.wh-store:last-child{border-bottom:0}.wh-store>view{flex:1;min-width:0}.wh-store-cover{width:5.5em;height:5.5em;flex-shrink:0;border-radius:.3em;background:#444b68;padding:.5em;box-sizing:border-box}.wh-store .wh-tag{font-size:.7em}.wh-store .wh-muted{font-size:.75em}.wh-confirm-mask{z-index:120}.wh-dialog>.wh-datum{font-size:.85em}
</style>
